<?php $destination=match($layer){'organizations'=>'/organization','mentors'=>'/mentor/profile',default=>'/experience'}; ?>
<article class="card atlas-result"><span class="service-icon"><?= $this->icon(match($layer){'organizations'=>'home','mentors'=>'user',default=>'book'}) ?></span><h3><a href="<?= $this->h($this->url($destination.'?id='.$row['id'])) ?>"><?= $this->h($row['title']) ?></a></h3><?php if(!empty($row['province_name'])): ?><p class="small muted"><?= $this->icon('pin') ?><?= $this->h($row['province_name'].' · '.($row['county_name']??'شهرستان ثبت نشده')) ?></p><?php endif; ?><p><?= $this->h($this->excerpt($row['summary']??'',190)) ?></p><?php if($layer!=='experiences'): ?><span class="tag"><?= $this->number($row['matched_experiences']) ?> تجربهٔ مرتبط با این انتخاب</span><?php if($layer==='organizations'): ?><span class="small muted"><?= $this->number($row['total_experiences']??0) ?> تجربه در کل · <?= $this->number($row['total_mentors']??0) ?> مرشد</span><?php endif; ?><?php elseif(!empty($row['display_name'])): ?><p class="small muted">مرشد: <?= $this->h($row['display_name']) ?></p><?php endif; ?><a class="primary" href="<?= $this->h($this->url($destination.'?id='.$row['id'])) ?>"><?= $layer==='experiences'?'خواندن تجربه':($layer==='organizations'?'شناخت مجموعه':'شناخت مرشد و گفت‌وگو') ?><?= $this->icon('arrow') ?></a></article>
